import{_ as r,a0 as s,w as l,s as m,ao as i,I as a,x as p,a1 as e,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"Nmap--不是只能用于做坏事！ | LCTT x X-CMD","titleTemplate":false,"description":"Nmap--不是只能用于做坏事！ | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Nmap--不是只能用于做坏事！ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Nmap--不是只能用于做坏事！ | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150306 Nmap--Not Just for Evil","title":"Nmap--不是只能用于做坏事！","tag":"201504","desc":""},"relativePath":"201504/20150306 Nmap--Not Just for Evil.md","filePath":"[post].md"}'),u={name:"201504/20150306 Nmap--Not Just for Evil.md"};function d(f,t,N,T,w,x){const o=s("Link");return l(),m("div",null,[t[13]||(t[13]=i(`<h1 id="nmap-不是只能用于做坏事" tabindex="-1">Nmap--不是只能用于做坏事！ <a class="header-anchor" href="#nmap-不是只能用于做坏事" aria-label="Permalink to “Nmap--不是只能用于做坏事！”">​</a></h1><p>如果SSH是系统管理员世界的&quot;瑞士军刀&quot;的话，那么Nmap就是一盒炸药。炸药很容易被误用然后将你的双脚崩掉，但是也是一个很有威力的工具，能够胜任一些看似无法完成的任务。</p><p>大多数人想到Nmap时，他们想到的是扫描服务器，查找开放端口来实施攻击。然而，在过去的这些年中，这样的超能力在当你管理服务器或计算机遇到问题时也是非常的有用。无论是你试图找出在你的网络上有哪些类型的服务器使用了指定的IP地址，或者尝试锁定一个新的NAS设备，以及扫描网络等，都会非常有用。</p><p>下图显示了我的QNAP NAS的网络扫描结果。我使用该设备的唯一目的是为了NFS和SMB文件共享，但是你可以看到，它包含了一大堆大开大敞的端口。如果没有Nmap，很难发现机器到底在运行着什么玩意儿。</p><p><img src="http://www.linuxjournal.com/files/linuxjournal.com/ufiles/imagecache/large-550px-centered/u1002061/11825nmapf1.jpg" alt=""></p><p><em>网络扫描</em></p><p>另外一个可能你没想到的用途是用它来扫描一个网络。你甚至根本不需要root的访问权限，而且你也可以非常容易地来指定你想要扫描的网络地址块，例如输入：</p><pre><code>nmap 192.168.1.0/24
</code></pre><p>上述命令会扫描我的局域网中全部的254个可用的IP地址，让我可以知道那个是可以Ping的，以及那些端口是开放的。如果你刚刚在网络上添加一个新的硬件，但是不知道它通过DHCP获取的IP地址是什么，那么此时Nmap就是无价之宝。例如，上述命令在我的网络中揭示了这个问题：</p><pre><code>Nmap scan report for TIVO-8480001903CCDDB.brainofshawn.com (192.168.1.220)
Host is up (0.0083s latency).
Not shown: 995 filtered ports
PORT     STATE  SERVICE
80/tcp   open   http
443/tcp  open   https
2190/tcp open   tivoconnect
2191/tcp open   tvbus
9080/tcp closed glrpc
</code></pre><p>它不仅显示了新的Tivo 设备，而且还告诉我那些端口是开放的。由于它的可靠性、可用性以及“黑边帽子”的能力，Nmap获得了本月的 &lt;&lt;编辑推荐&gt;&gt;奖。这不是一个新的程序，但是如果你是一个linux用户的话，你应该玩玩它。</p><hr>`,12)),a("p",null,[t[1]||(t[1]=p("via: ",-1)),e(o,{href:"http://www.linuxjournal.com/content/nmap%E2%80%94not-just-evil"},{default:n(()=>[...t[0]||(t[0]=[p("http://www.linuxjournal.com/content/nmap—not-just-evil",-1)])]),_:1})]),a("p",null,[t[5]||(t[5]=p("作者：",-1)),e(o,{href:"http://www.linuxjournal.com/users/shawn-powers"},{default:n(()=>[...t[2]||(t[2]=[p("Shawn Powers",-1)])]),_:1}),t[6]||(t[6]=p(" 译者：",-1)),e(o,{href:"https://github.com/theo-l"},{default:n(()=>[...t[3]||(t[3]=[p("theo-l",-1)])]),_:1}),t[7]||(t[7]=p(" 校对：",-1)),e(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[4]||(t[4]=[p("wxy",-1)])]),_:1})]),a("p",null,[t[10]||(t[10]=p("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[8]||(t[8]=[p("LCTT",-1)])]),_:1}),t[11]||(t[11]=p(" 原创翻译，",-1)),e(o,{href:"http://linux.cn/"},{default:n(()=>[...t[9]||(t[9]=[p("Linux中国",-1)])]),_:1}),t[12]||(t[12]=p(" 荣誉推出",-1))])])}const S=r(u,[["render",d]]);export{P as __pageData,S as default};
